package meteora_damm_v2

import (
	"encoding/base64"
	"testing"

	bin "github.com/gagliardetto/binary"
	"github.com/test-go/testify/assert"
	"github.com/test-go/testify/require"
)

func TestDecodingPool(t *testing.T) {
	// Example data from mainnet
	// Source: https://explorer.solana.com/address/D9iJqMbgQJLFt5PAAiTJTMNsMAMueukzoe1EK2r1g3WH
	data := ""
	bytes, err := base64.StdEncoding.DecodeString(data)
	require.NoError(t, err)

	var pool Pool
	err = bin.NewBorshDecoder(bytes).Decode(&pool)
	require.NoError(t, err)

	assert.Equal(t, int(10000000), int(pool.PoolFees.BaseFee.CliffFeeNumerator))
	assert.Equal(t, "bnWKPK7YTUJTe3A3HTGEJrUEoAddRgRjWSwf7MwxMP3", pool.TokenAMint.String())
	assert.Equal(t, "9LzCMqDgTKYz9Drzqnpgee3SGa89up3a247ypMj2xrqM", pool.TokenBMint.String())
	assert.Equal(t, "31500505798829827035928817465053256", pool.Liquidity.String())
	assert.Equal(t, "3838765547535761", pool.FeeBPerLiquidity.String())
	assert.Equal(t, int(1759932808), int(pool.ActivationPoint))
	// assert.Equal(t, "", pool.FeeBPerLiquidity.String())
}

func TestDecodingPositionState(t *testing.T) {
	// Example data from mainnet
	// Source: https://explorer.solana.com/address/5bYLydDXt1K5zroychcbrVbhGRUpheXdq5w41uccazPB
	data := ""
	bytes, err := base64.StdEncoding.DecodeString(data)
	require.NoError(t, err)

	var position PositionState
	err = bin.NewBorshDecoder(bytes).Decode(&position)
	require.NoError(t, err)

	assert.Equal(t, "D9iJqMbgQJLFt5PAAiTJTMNsMAMueukzoe1EK2r1g3WH", position.Pool.String())
	assert.Equal(t, "A87b7M7UnQCicj6Ui7ktCL9CoN9xnnLbp3bezoDS26uX", position.NftMint.String())
	assert.Equal(t, "15750252899414913517964408732526628", position.PermanentLockedLiquidity.String())
}
